END TRY
BEGIN CATCH
  IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
  THROW;
END CATCH;

SELECT GECODEMP, COUNT(*) AS ProductosConImagen,
       SUM(DATALENGTH(PRODImagen)) AS BytesImagenes
FROM dbo.SSP06MAProducto
WHERE GECODEMP=6100 AND PRODImagen IS NOT NULL
GROUP BY GECODEMP;
